-- Optional: store outputs generated by skills for sharing/history
create table if not exists public.skill_outputs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  entity_id uuid not null references public.entities (id) on delete cascade,
  skill_id text not null references public.skills (id) on delete cascade,
  content_type text not null check (content_type in ('text', 'image', 'audio', 'video', 'json')),
  storage_path text,
  public_url text,
  text_content text,
  metadata jsonb default '{}'::jsonb,
  created_at timestamptz default now()
);

alter table public.skill_outputs enable row level security;

create policy "Users manage own skill outputs"
  on public.skill_outputs for all
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

create index if not exists skill_outputs_user_entity on public.skill_outputs (user_id, entity_id);

